<script setup lang="ts">
const { t } = useLocale()
const name=ref(''), email=ref(''), phone=ref(''), secret=ref(''), error=ref(''), loading=ref(false), registered=ref(false)
async function register(){error.value='';loading.value=true;try{await $fetch('/api/auth/register',{method:'POST',body:{name:name.value,email:email.value,phone:phone.value,password:secret.value}});registered.value=true}catch(e:any){error.value=e?.data?.statusMessage==='EMAIL_ALREADY_REGISTERED'?t('emailRegistered'):e?.statusCode===503?t('dbUnavailable'):t('registerFailed')}finally{loading.value=false}}
</script>
<template><div class="mx-auto max-w-md"><div v-if="registered" class="rounded-2xl border bg-white p-6 text-center"><div class="text-5xl">✓</div><h1 class="mt-4 text-2xl font-bold">{{ t('registrationSuccessTitle') }}</h1><p class="mt-3 text-slate-600">{{ t('registrationSuccessText') }}</p><button class="mt-6 w-full rounded-xl bg-slate-900 p-3 font-semibold text-white" @click="navigateTo('/account')">{{ t('continueToAccount') }}</button></div><template v-else><h1 class="text-3xl font-bold">{{ t('register') }}</h1><form class="mt-6 space-y-4" @submit.prevent="register"><input v-model="name" required :placeholder="t('name')" class="w-full rounded-xl border p-3"><input v-model="email" type="email" required placeholder="Email" class="w-full rounded-xl border p-3"><input v-model="phone" required :placeholder="t('phone')" class="w-full rounded-xl border p-3"><input v-model="secret" type="password" minlength="8" required :placeholder="t('password')" class="w-full rounded-xl border p-3"><p v-if="error" class="rounded-xl bg-red-50 p-3 text-red-700">{{ error }}</p><button :disabled="loading" class="w-full rounded-xl bg-slate-900 p-3 font-semibold text-white">{{loading?t('createLoading'):t('createAccount')}}</button></form></template></div></template>
